1	//! Asking a checker for the component a session was just asked about (ADR 0022).
2	//!
3	//! The structural answer is always computed first and is a complete answer on its own. With a [`SemanticProvider`]
4	//! attached, [`SemanticHook::refine`] asks the checker for exactly that component, waits a bounded time, and merges
5	//! its props over the structural ones. A checker that is slower than the budget leaves the structural answer in
6	//! place, and its late answer is kept for the next request of the same, unedited component.
7	//!
8	//! There is one request in flight per component and version of its file: a caller that finds one waits on it instead
9	//! of asking again, and a caller raises a request it joins to its own class, so a story asked while its own prefetch
10	//! runs is answered when the prefetch is.
11	//!
12	//! A request nobody waits for is cancelled when its answer would not be read: an edit superseded the revision it was
13	//! asked at ([`SemanticHook::invalidate`]), or the client no longer shows its component ([`SemanticHook::cancel`]).
14	//! A checker drops it before converting it; one already converting it finishes.
15	//!
16	//! An answer describes the component's props as the checker read them, which depends on every file the component
17	//! imports, not only its own. So the session drops every answer when any source file changes
18	//! ([`SemanticHook::invalidate`]), and an answer that was still on its way then is neither kept nor joined. The same
19	//! call tells the checker which files changed, since a warm one answers from what it read before (ADR 0026 S6).
20	
21	use std::hash::{Hash, Hasher};
22	use std::sync::atomic::{AtomicBool, Ordering};
23	use std::sync::{Arc, Condvar, Mutex, PoisonError};
24	use std::time::Duration;
25	
26	use rustc_hash::{FxHashMap, FxHashSet, FxHasher};
27	
28	use super::ComponentAnswer;
29	use crate::pipeline::HtmlAttributeMode;
30	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
31	use crate::types::options::CollapseContext;
32	use crate::types::semantic::{
33	    Delivery, Layering, MergedProps, Priority, PropInterner, SemanticComponent, SemanticFallback, SemanticOutcome,
34	    SemanticProp, SemanticProvider, SemanticTarget, SharedPriority, SourceChange, Superseding, drop_superseded,
35	    merge_semantic_props, unread_diagnostic,
36	};
37	
38	/// What one request of the checker made of a component: the component it found, if any, and what the checker said
39	/// about the request itself (an edit it was not told about, why a component kept its structural result). Both are the
40	/// answer, so a late answer, a joined one and every request the cache serves it to carry both.
41	#[derive(Clone, Default)]
42	struct Answered {
43	    component: Option<Arc<SemanticComponent>>,
44	    diagnostics: Vec<Diagnostic>,
45	}
46	
47	/// What became of one request to the checker, for every caller that waited on it.
48	#[derive(Clone)]
49	enum Settled {
50	    /// The checker answered: what is kept for the component, and what an unavailable checker says once per session.
51	    Answered { answered: Answered, once: Vec<Diagnostic> },
52	    /// The checker stopped without answering.
53	    Stopped,
54	    /// The request was cancelled before the checker converted it ([`SharedPriority::cancel`]): not an answer, and not
55	    /// a checker that stopped, so a caller reads it as one still on its way.
56	    Cancelled,
57	}
58	
59	/// A request in flight. Every caller for the same component and version of its file waits on it instead of asking the
60	/// checker again.
61	struct Pending {
62	    /// What the checker answers it at; a caller someone is waiting for raises it on joining.
63	    priority: SharedPriority,
64	    settled: Mutex<Option<Settled>>,
65	    ready: Condvar,
66	}
67	
68	impl Pending {
69	    fn new(priority: Priority) -> Self {
70	        Self { priority: SharedPriority::new(priority), settled: Mutex::new(None), ready: Condvar::new() }
71	    }
72	
73	    fn settle(&self, settled: Settled) {
74	        *self.settled.lock().unwrap_or_else(PoisonError::into_inner) = Some(settled);
75	        self.ready.notify_all();
76	    }
77	
78	    /// What became of the request, if that is known within `wait`.
79	    fn wait(&self, wait: Duration) -> Option<Settled> {
80	        let settled = self.settled.lock().unwrap_or_else(PoisonError::into_inner);
81	        let (settled, _) = self
82	            .ready
83	            .wait_timeout_while(settled, wait, |settled| settled.is_none())
84	            .unwrap_or_else(PoisonError::into_inner);
85	        settled.clone()
86	    }
87	}
88	
89	/// What the checker said about one component at one version of its file, what it is still being asked, and the
90	/// generation they belong to.
91	#[derive(Default)]
92	struct AnswerCache {
93	    /// Raised by every [`SemanticHook::invalidate`]; an answer asked for under an earlier one is not stored.
94	    generation: u64,
95	    answers: FxHashMap<(String, u64), Answered>,
96	    /// Requests in flight under the current generation, by the same key as `answers`.
97	    pending: FxHashMap<(String, u64), Arc<Pending>>,
98	    /// The one copy of each prop the kept answers hold, for this generation.
99	    props: PropInterner,
100	}
101	
102	impl AnswerCache {
103	    /// `component` with each prop the one copy the kept answers share. A design system's components repeat the same
104	    /// props (Chakra's about a thousand style props each), and an answer kept with its own copies held about 6.7 MiB
105	    /// per Chakra component, so a session that answered a few hundred stories held gigabytes.
106	    fn shared(&self, component: Arc<SemanticComponent>) -> Arc<SemanticComponent> {
107	        let SemanticComponent { key, props, composes, whole } = Arc::unwrap_or_clone(component);
108	        let props = props.into_iter().map(|prop| self.props.share_arc(prop)).collect();
109	        Arc::new(SemanticComponent { key, props, composes, whole })
110	    }
111	}
112	
113	type Answers = Mutex<AnswerCache>;
114	
115	/// Where a request finds its answer.
116	enum Found {
117	    /// An answer kept from an earlier request.
118	    Cached(Answered),
119	    /// A request already in flight, to wait on.
120	    Joined(Arc<Pending>),
121	    /// Nothing: this caller asks, and others join it.
122	    Asking(Arc<Pending>),
123	}
124	
125	/// How long a request for a component the structural pass lists no props for waits for the checker, unless the session
126	/// says otherwise ([`SemanticHook::wait_empty`]): an empty answer is not worth showing early, and Chakra's `Button` takes
127	/// 0.4 to 0.8 s.
128	pub(crate) const DEFAULT_WAIT_EMPTY: Duration = Duration::from_secs(2);
129	
130	/// What an answer says when the checker had not answered within the wait and the structural props stand in for its.
131	const CHECKER_PENDING: &str = "the TypeScript checker has not answered yet; the structural props are used, and the \
132	                               checker's replace them on the next request";
133	
134	/// Whether `answer`'s props are the structural ones because the checker had not answered within the wait: asked again
135	/// once the checker has answered, and before any source file changes, the session answers with the checker's props.
136	/// The one place that decides it, for hosts that show an answer and replace it later.
137	pub fn awaits_checker(answer: &ComponentAnswer) -> bool {
138	    answer.diagnostics.iter().any(|diagnostic| {
139	        diagnostic.code == DiagnosticCode::SemanticBackend
140	            && diagnostic.severity == DiagnosticSeverity::Info
141	            && diagnostic.message == CHECKER_PENDING
142	    })
143	}
144	
145	pub(crate) struct SemanticHook {
146	    provider: Arc<dyn SemanticProvider>,
147	    /// How long a request waits for the checker before it takes the structural answer.
148	    wait: Duration,
149	    /// How long it waits instead when the structural answer has no props; never less than `wait`.
150	    wait_empty: Duration,
151	    answers: Arc<Answers>,
152	    /// Set once the checker has been reported unavailable, so a session says so once, not per component.
153	    warned: AtomicBool,
154	}
155	
156	impl SemanticHook {
157	    pub(crate) fn new(provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
158	        Self {
159	            provider,
160	            wait,
161	            wait_empty: DEFAULT_WAIT_EMPTY,
162	            answers: Arc::new(Mutex::new(AnswerCache::default())),
163	            warned: AtomicBool::new(false),
164	        }
165	    }
166	
167	    /// Sets how long a request for a component with no structural props waits for the checker. A wait at most `wait`
168	    /// gives such a component the same wait as every other.
169	    pub(crate) fn wait_empty(&mut self, wait_empty: Duration) {
170	        self.wait_empty = wait_empty;
171	    }
172	
173	    /// The wait for `answer`. Nobody waits for a neighbour or background request: its answer is kept for the request
174	    /// that follows.
175	    /// Someone does for an interactive one, and longer when the structural pass found no props, since there is nothing
176	    /// to show before the checker answers. Any prop, even a degraded one, is an answer worth showing at the short wait.
177	    fn wait_for(&self, answer: &ComponentAnswer, priority: Priority) -> Duration {
178	        match (priority, answer.entry.props.is_empty()) {
179	            (Priority::Neighbour | Priority::Background, _) => Duration::ZERO,
180	            (Priority::Interactive, true) => self.wait_empty.max(self.wait),
181	            (Priority::Interactive, false) => self.wait,
182	        }
183	    }
184	
185	    /// Forget every answer, refuse the ones still being waited for, and tell the checker what changed: a source file
186	    /// changed, and the checker's props for any component can depend on it. The next request of each component asks
187	    /// the checker again, after it has been told, rather than joining a request asked before the change. A request
188	    /// nobody waits for is cancelled: its answer, of the superseded revision, would not be kept, so a checker that has
189	    /// not started it drops it. One someone waits for is still answered, after the change.
190	    pub(crate) fn invalidate(&self, change: SourceChange) {
191	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
192	        cache.generation += 1;
193	        cache.answers.clear();
194	        for pending in cache.pending.values() {
195	            pending.priority.cancel();
196	        }
197	        cache.pending.clear();
198	        cache.props = PropInterner::default();
199	        self.provider.changed(change);
200	    }
201	
202	    /// Cancels the requests in flight for `keys` that nobody waits for: the client no longer shows those components,
203	    /// so a checker that has not started them drops them. A later request asks again rather than joining a cancelled
204	    /// one; a request someone waits for, or one the checker is already converting, stays registered, so a later request
205	    /// joins it, and is answered (and kept) as before.
206	    pub(crate) fn cancel(&self, keys: &[String]) {
207	        let keys: FxHashSet<&str> = keys.iter().map(String::as_str).collect();
208	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
209	        cache.pending.retain(|(key, _), pending| !(keys.contains(key.as_str()) && pending.priority.cancel()));
210	    }
211	
212	    /// `answer` with the checker's props, when it has them within the wait `priority` gives it.
213	    pub(crate) fn refine(
214	        &self,
215	        mut answer: ComponentAnswer,
216	        mode: HtmlAttributeMode,
217	        cx: CollapseContext,
218	        priority: Priority,
219	    ) -> ComponentAnswer {
220	        let mode = crate::react_types::react_attribute_mode(mode, crate::react_types::expanded(&answer.entry, cx.mode));
221	        // The checker converts only the props this merge keeps, decided from the structural answer and `cx`: an answer
222	        // is kept and joined for those too, so another structural answer is never merged with props left unconverted.
223	        let layering = Layering::of(&answer.entry, cx);
224	        let stamp = std::fs::read(&answer.entry.file_path).map(|bytes| {
225	            let mut hasher = FxHasher::default();
226	            bytes.hash(&mut hasher);
227	            layering.hash(&mut hasher);
228	            hasher.finish()
229	        });
230	        let cache_key = stamp.ok().map(|stamp| (answer.key.clone(), stamp));
231	
232	        let (found, generation) = self.find(cache_key.as_ref(), priority);
233	        let pending = match found {
234	            Found::Cached(cached) => {
235	                self.apply(&mut answer, cached, mode, cx);
236	                return answer;
237	            }
238	            Found::Joined(pending) => pending,
239	            Found::Asking(pending) => {
240	                self.ask(target_of(&answer, mode, layering), &pending, cache_key, generation);
241	                pending
242	            }
243	        };
244	
245	        match pending.wait(self.wait_for(&answer, priority)) {
246	            Some(Settled::Answered { answered, once }) => {
247	                for diagnostic in once {
248	                    if !self.warned.swap(true, Ordering::Relaxed) {
249	                        answer.diagnostics.push(diagnostic);
250	                    }
251	                }
252	                self.apply(&mut answer, answered, mode, cx);
253	            }
254	            Some(Settled::Stopped) => {
255	                let mut stopped = Diagnostic::new(
256	                    DiagnosticSeverity::Warning,
257	                    DiagnosticCode::SemanticBackend,
258	                    "the TypeScript checker stopped without answering; the structural props are used",
259	                );
260	                stopped.affects = vec![answer.key.clone()];
261	                answer.diagnostics.push(stopped);
262	            }
263	            Some(Settled::Cancelled) | None => {
264	                let mut pending =
265	                    Diagnostic::new(DiagnosticSeverity::Info, DiagnosticCode::SemanticBackend, CHECKER_PENDING);
266	                pending.affects = vec![answer.key.clone()];
267	                answer.diagnostics.push(pending);
268	            }
269	        }
270	        answer
271	    }
272	
273	    /// The kept answer for `key`, else the request in flight for it (raised to `priority` when that goes first), else a
274	    /// new request this caller makes, registered so the next caller joins it. One lock, so two callers never both ask.
275	    /// A file that could not be read has no key: its request is neither kept nor joined.
276	    fn find(&self, key: Option<&(String, u64)>, priority: Priority) -> (Found, u64) {
277	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
278	        let generation = cache.generation;
279	        if let Some(key) = key {
280	            if let Some(cached) = cache.answers.get(key) {
281	                return (Found::Cached(cached.clone()), generation);
282	            }
283	            if let Some(pending) = cache.pending.get(key) {
284	                pending.priority.raise_to(priority);
285	                return (Found::Joined(pending.clone()), generation);
286	            }
287	        }
288	        let pending = Arc::new(Pending::new(priority));
289	        if let Some(key) = key {
290	            cache.pending.insert(key.clone(), pending.clone());
291	        }
292	        (Found::Asking(pending), generation)
293	    }
294	
295	    /// Asks the checker about `target`. Its outcome settles `pending` for every caller waiting on it and is
296	    /// kept for the next request, unless the cache was invalidated since `generation`. Called without the cache's lock,
297	    /// since a provider may deliver at once.
298	    fn ask(&self, target: SemanticTarget, pending: &Arc<Pending>, key: Option<(String, u64)>, generation: u64) {
299	        let answers = self.answers.clone();
300	        let asked = target.key.clone();
301	        let settling = pending.clone();
302	        let delivery = Delivery::new(move |outcome| {
303	            let mut settled = match outcome {
304	                Some(outcome) => {
305	                    let Read { answered, once } = read_outcome(&asked, outcome);
306	                    Settled::Answered { answered, once }
307	                }
308	                None if settling.priority.is_cancelled() => Settled::Cancelled,
309	                None => Settled::Stopped,
310	            };
311	            if let Some(key) = key {
312	                let mut cache = answers.lock().unwrap_or_else(PoisonError::into_inner);
313	                if cache.pending.get(&key).is_some_and(|registered| Arc::ptr_eq(registered, &settling)) {
314	                    cache.pending.remove(&key);
315	                }
316	                if let Settled::Answered { answered, .. } = &mut settled
317	                    && cache.generation == generation
318	                {
319	                    answered.component = answered.component.take().map(|component| cache.shared(component));
320	                    cache.answers.insert(key, answered.clone());
321	                }
322	            }
323	            settling.settle(settled);
324	        });
325	        self.provider.request_at(vec![target], pending.priority.clone(), delivery);
326	    }
327	
328	    /// Merges what the checker made of the component into `answer`: its props, if it found the component, then what it
329	    /// said about the request. The structural diagnostics its props supersede go first, so the checker's are never
330	    /// read as structural.
331	    fn apply(&self, answer: &mut ComponentAnswer, answered: Answered, mode: HtmlAttributeMode, cx: CollapseContext) {
332	        let Answered { component, diagnostics } = answered;
333	        let Some(component) = component else {
334	            answer.diagnostics.extend(diagnostics);
335	            return;
336	        };
337	        let structural = answer.entry.props.clone();
338	        let visible = crate::react_types::visible_rows(&answer.entry);
339	        let used: Vec<&Arc<SemanticProp>> = component
340	            .props
341	            .iter()
342	            .filter(|prop| crate::react_types::checker_prop_kept(mode, &prop.name, prop.react_declared, &visible))
343	            .collect();
344	        // The props of a collapsed source are its layer's, not listed again.
345	        let (used, notable) =
346	            crate::types::semantic::layer_checker_props(&mut answer.entry, used, &component.whole, cx);
347	        // A structural prop the checker did not return keeps its structural type, opaque or not, and a structural
348	        // diagnostic naming the component may be about it.
349	        let structural_left = structural
350	            .iter()
351	            .any(|(name, prop)| prop.prop_type.holds_opaque() && !used.iter().any(|answered| answered.name == *name));
352	        let MergedProps { kept, unread, diagnostics: syntax } = merge_semantic_props(
353	            &mut answer.entry,
354	            used.into_iter(),
355	            component.composes.as_deref(),
356	            &mut FxHashMap::default(),
357	        );
358	        crate::types::semantic::move_notable(&mut answer.entry, &notable);
359	        crate::types::semantic::listed_props_leave_layers(&mut answer.entry, true);
360	        crate::relevance::narrow(&mut answer.entry);
361	        let superseding = Superseding::new(&answer.key, &answer.entry, structural_left);
362	        drop_superseded(&mut answer.diagnostics, &[superseding]);
363	        answer.diagnostics.extend(diagnostics);
364	        let mut provenance = Diagnostic::new(
365	            DiagnosticSeverity::Info,
366	            DiagnosticCode::SemanticBackend,
367	            match kept {
368	                0 => "1 component(s) resolved by the TypeScript checker".to_string(),
369	                kept => format!(
370	                    "1 component(s) resolved by the TypeScript checker; {kept} prop(s) it did not report keep their \
371	                     structural type"
372	                ),
373	            },
374	        );
375	        provenance.affects = vec![answer.key.clone()];
376	        answer.diagnostics.push(provenance);
377	        answer.diagnostics.extend(syntax);
378	        if unread > 0 {
379	            answer.diagnostics.push(unread_diagnostic(unread, vec![answer.key.clone()]));
380	        }
381	    }
382	}
383	
384	/// What the checker is asked about `answer`'s component: its props under `mode`, converted only where the merge with
385	/// `layering` keeps them.
386	fn target_of(answer: &ComponentAnswer, mode: HtmlAttributeMode, layering: Layering) -> SemanticTarget {
387	    SemanticTarget {
388	        key: answer.key.clone(),
389	        file_path: answer.entry.file_path.clone(),
390	        display_name: answer.entry.display_name.clone(),
391	        exports: answer.entry.exports.clone(),
392	        described: answer
393	            .entry
394	            .props
395	            .values()
396	            .filter(|prop| !prop.description.is_empty())
397	            .map(|prop| prop.name.clone())
398	            .collect(),
399	        react_wanted: crate::react_types::react_props_wanted_for(mode, &answer.entry),
400	        layering: Some(layering),
401	    }
402	}
403	
404	/// An outcome read for the component asked about.
405	struct Read {
406	    /// What is kept for the next request: the component and what the checker said about the request, each diagnostic
407	    /// naming the component.
408	    answered: Answered,
409	    /// What an unavailable checker says, which a session says once and not per component, so it is not kept.
410	    once: Vec<Diagnostic>,
411	}
412	
413	/// The answer for the component whose output key is `asked`, and the diagnostics the request produced: a warning that
414	/// came with an answer (an edit the checker was not told about) is about this request, and its fallback's reason says
415	/// why the component kept its structural result. An answer or fallback for another key is not this component's.
416	fn read_outcome(asked: &str, outcome: SemanticOutcome) -> Read {
417	    let SemanticOutcome { components, fallbacks, diagnostics: reported } = outcome;
418	    // Only an outcome with no answer at all says the checker is unavailable.
419	    let unavailable = components.is_empty() && fallbacks.is_empty();
420	    let mut read = Read { answered: Answered::default(), once: Vec::new() };
421	    for mut diagnostic in reported {
422	        diagnostic.affects = vec![asked.to_owned()];
423	        if unavailable && diagnostic.severity == DiagnosticSeverity::Warning {
424	            read.once.push(diagnostic);
425	        } else {
426	            read.answered.diagnostics.push(diagnostic);
427	        }
428	    }
429	    for SemanticFallback { key, reason } in fallbacks {
430	        if key != asked {
431	            continue;
432	        }
433	        let mut info = Diagnostic::new(
434	            DiagnosticSeverity::Info,
435	            DiagnosticCode::SemanticBackend,
436	            format!("1 component(s) kept their structural result: {reason}"),
437	        );
438	        info.affects = vec![key];
439	        read.answered.diagnostics.push(info);
440	    }
441	    read.answered.component = components.into_iter().find(|found| found.key == asked).map(Arc::new);
442	    read
443	}
