446	mod tests {
447	    use super::*;
448	    use crate::types::PropType;
449	
450	    fn component(key: &str, names: &[&str]) -> Arc<SemanticComponent> {
451	        let props = names
452	            .iter()
453	            .map(|name| {
454	                Arc::new(SemanticProp {
455	                    name: (*name).to_owned(),
456	                    prop_type: PropType::String,
457	                    required: false,
458	                    description: String::new(),
459	                    tags: Default::default(),
460	                    parent: None,
461	                    declarations: Vec::new(),
462	                    react_declared: false,
463	                })
464	            })
465	            .collect();
466	        Arc::new(SemanticComponent { key: key.to_owned(), props, composes: None, whole: Vec::new() })
467	    }
