469	    #[test]
470	    fn kept_answers_share_one_copy_of_an_equal_prop_until_the_cache_is_invalidated() {
471	        let mut cache = AnswerCache::default();
472	        let first = cache.shared(component("A", &["color", "size"]));
473	        let second = cache.shared(component("B", &["color", "label"]));
474	
475	        assert!(Arc::ptr_eq(&first.props[0], &second.props[0]), "both answers hold the one `color`");
476	        assert!(!Arc::ptr_eq(&first.props[1], &second.props[1]));
477	        assert_eq!(second.key, "B");
478	        assert_eq!(second.props.iter().map(|prop| prop.name.as_str()).collect::<Vec<_>>(), ["color", "label"]);
479	
480	        // What `invalidate` does to the cache: a later answer no longer reaches the props of the dropped ones.
481	        cache.props = PropInterner::default();
482	        let third = cache.shared(component("C", &["color"]));
483	        assert!(!Arc::ptr_eq(&first.props[0], &third.props[0]));
484	    }
