486	    /// A checker that holds every request with its priority; the test answers one or reads its priority.
487	    #[derive(Default)]
488	    struct Holding(Mutex<Vec<(String, SharedPriority, Option<Delivery>)>>);
489	
490	    impl Holding {
491	        /// The key, priority now and whether it was cancelled, of every request in the order asked.
492	        fn asked(&self) -> Vec<(String, Priority, bool)> {
493	            let held = self.0.lock().unwrap();
494	            held.iter().map(|(key, priority, _)| (key.clone(), priority.get(), priority.is_cancelled())).collect()
495	        }
496	
497	        /// What the worker does when it takes request `n` to convert it.
498	        fn start(&self, n: usize) {
499	            assert!(self.0.lock().unwrap()[n].1.start());
500	        }
501	
502	        fn answer(&self, n: usize) {
503	            let (key, delivery) = {
504	                let mut held = self.0.lock().unwrap();
505	                (held[n].0.clone(), held[n].2.take().unwrap())
506	            };
507	            let outcome =
508	                SemanticOutcome { components: vec![(*component(&key, &["label"])).clone()], ..Default::default() };
509	            delivery.deliver(Some(outcome));
510	        }
511	    }
512	
513	    impl SemanticProvider for Holding {
514	        fn request(&self, targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome> {
515	            let (sender, receiver) = std::sync::mpsc::channel();
516	            let delivery = Delivery::new(move |outcome| {
517	                if let Some(outcome) = outcome {
518	                    sender.send(outcome).ok();
519	                }
520	            });
521	            self.request_at(targets, SharedPriority::new(Priority::Interactive), delivery);
522	            receiver
523	        }
524	
525	        fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
526	            let key = targets.into_iter().next().unwrap().key;
527	            self.0.lock().unwrap().push((key, priority, Some(delivery)));
528	        }
529	    }
530	
531	    fn session(files: &[(&str, &str)]) -> (tempfile::TempDir, Arc<crate::pipeline::WatchSession>, Arc<Holding>) {
532	        let dir = tempfile::tempdir().unwrap();
533	        let root = camino::Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
534	        for (name, source) in files {
535	            std::fs::write(root.join(name), source).unwrap();
536	        }
537	        let checker = Arc::new(Holding::default());
538	        let options = crate::pipeline::PipelineOptions { src_dirs: vec![root], ..Default::default() };
539	        let session =
540	            crate::pipeline::WatchSession::lazy(options).with_semantic(checker.clone(), Duration::from_secs(60));
541	        drop(session.initialize());
542	        (dir, Arc::new(session), checker)
543	    }
544	
545	    const BUTTON: &str = "export function Button(props: { label: string }) { return null; }";
546	    const CARD: &str = "export function Card(props: { title: string }) { return null; }";
547	
548	    /// A prefetch of a story the client navigated away from is cancelled, so the checker drops it before converting it;
549	    /// the next request of that component asks again rather than joining it. A prefetch a story joined is waited for
550	    /// and is not cancelled. On the base nothing could cancel a request.
551	    #[test]
552	    fn a_request_for_a_component_nobody_shows_is_dropped_before_conversion() {
553	        let (_dir, session, checker) = session(&[("Button.tsx", BUTTON), ("Card.tsx", CARD)]);
554	        drop(session.components_as_neighbours(&["Button".to_string(), "Card".to_string()]));
555	        let story = {
556	            let session = session.clone();
557	            std::thread::spawn(move || session.component("Card").unwrap())
558	        };
559	        while checker.asked()[1].1 != Priority::Interactive {
560	            std::thread::yield_now();
561	        }
562	
563	        session.cancel_components(&["Button".to_string(), "Card".to_string()]);
564	
565	        assert_eq!(
566	            checker.asked(),
567	            [("Button".to_string(), Priority::Neighbour, true), ("Card".to_string(), Priority::Interactive, false)]
568	        );
569	        checker.answer(1);
570	        assert!(story.join().unwrap().entry.props.contains_key("label"));
571	        drop(session.components_as_neighbours(&["Button".to_string()]));
572	        assert_eq!(checker.asked().len(), 3, "a cancelled request is not joined");
573	        assert_eq!(checker.asked()[2], ("Button".to_string(), Priority::Neighbour, false));
574	    }
575	
576	    /// A neighbour request the checker already took is converted whatever the client shows now: a cancel leaves it
577	    /// registered, so a request for the component joins it, and its one delivery settles both callers. On the base the
578	    /// cancel removed the entry and the second request started a second conversion.
579	    #[test]
580	    fn a_request_being_converted_survives_a_cancel_and_is_joined() {
581	        let (_dir, session, checker) = session(&[("Button.tsx", BUTTON)]);
582	        drop(session.components_as_neighbours(&["Button".to_string()]));
583	        checker.start(0);
584	
585	        session.cancel_components(&["Button".to_string()]);
586	        let story = {
587	            let session = session.clone();
588	            std::thread::spawn(move || session.component("Button").unwrap())
589	        };
590	        while checker.asked()[0].1 != Priority::Interactive {
591	            std::thread::yield_now();
592	        }
593	
594	        assert_eq!(checker.asked(), [("Button".to_string(), Priority::Interactive, false)]);
595	        checker.answer(0);
596	        assert!(story.join().unwrap().entry.props.contains_key("label"));
597	        assert_eq!(checker.asked().len(), 1, "one conversion served both");
598	    }
599	
600	    /// A checker that drops each request as cancelled the moment it is asked: a cancel that lands between a caller
601	    /// registering its request and reading it.
602	    struct CancelsAtOnce;
603	
604	    impl SemanticProvider for CancelsAtOnce {
605	        fn request(&self, _targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome> {
606	            std::sync::mpsc::channel().1
607	        }
608	
609	        fn request_at(&self, _targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
610	            assert!(priority.cancel());
611	            drop(delivery);
612	        }
613	    }
614	
615	    /// A cancelled request is not a checker that stopped: its caller is told the answer is still to come, with no
616	    /// warning.
617	    #[test]
618	    fn a_cancelled_request_is_not_reported_as_a_stopped_checker() {
619	        let dir = tempfile::tempdir().unwrap();
620	        std::fs::write(dir.path().join("Button.tsx"), BUTTON).unwrap();
621	        let root = camino::Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
622	        let options = crate::pipeline::PipelineOptions { src_dirs: vec![root], ..Default::default() };
623	        let session = crate::pipeline::WatchSession::lazy(options)
624	            .with_semantic(Arc::new(CancelsAtOnce), Duration::from_secs(60));
625	        drop(session.initialize());
626	
627	        let answer = session.components_as_neighbours(&["Button".to_string()]).remove(0).unwrap();
628	
629	        let messages: Vec<&str> = answer.diagnostics.iter().map(|d| d.message.as_str()).collect();
630	        assert_eq!(messages, [CHECKER_PENDING]);
631	    }
632	
633	    /// An edit cancels the requests of the revision before it that nobody waits for: their answers would not be kept.
634	    #[test]
635	    fn a_request_of_a_superseded_revision_is_dropped() {
636	        let (dir, session, checker) = session(&[("Button.tsx", BUTTON), ("Card.tsx", CARD)]);
637	        drop(session.components_in_background(&["Button".to_string()]));
638	        drop(session.components_as_neighbours(&["Card".to_string()]));
639	
640	        let file = camino::Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
641	        std::fs::write(file.join("Card.tsx"), CARD.replace("title", "heading")).unwrap();
642	        session.update_file(&file.join("Card.tsx"));
643	
644	        assert_eq!(
645	            checker.asked(),
646	            [("Button".to_string(), Priority::Background, true), ("Card".to_string(), Priority::Neighbour, true)]
647	        );
648	    }
649	}
