    assert_eq!(second.diagnostics, oracle.diagnostics);
    assert_eq!(checker.0.load(Ordering::SeqCst), 2);
}

fn session_of(project: &Project, checker: Arc<Fake>) -> WatchSession {
    session(project, checker, Duration::from_secs(5))
}

